import json, os, re, sys

base = "slack-api"
errors, warnings = [], []

# 1. SKILL.md exists
skill = os.path.join(base, "SKILL.md")
if not os.path.isfile(skill):
    errors.append("SKILL.md not found")
    sys.exit(1)

content = open(skill, encoding="utf-8").read()
if not content.startswith("---"):
    errors.append("No YAML frontmatter")

# 2. Frontmatter parse (mirror validate_skill.cjs)
parts = content.split("---")
if len(parts) < 3:
    errors.append("Invalid frontmatter format")
else:
    fm = parts[1]
    name = re.search(r"^name:\s*(.+)$", fm, re.M)
    desc = re.search(r"^description:\s*(?:'([^']*)'|\"([^\"]*)\"|(.+))$", fm, re.M)
    if not name: errors.append('Missing "name" in frontmatter')
    if not desc: errors.append("Missing description in frontmatter")
    else:
        d = (desc.group(1) or desc.group(2) or desc.group(3) or "").strip()
        if "\n" in d: errors.append("Description must be a single line")
        if len(d) > 1024: errors.append("Description too long")
        if not re.fullmatch(r"[a-z0-9-]+", name.group(1).strip()):
            errors.append('Name must be hyphen-case lowercase')

# 3. No TODO placeholders anywhere
for root, _, files in os.walk(base):
    for f in files:
        fp = os.path.join(root, f)
        if "TODO:" in open(fp, encoding="utf-8").read():
            warnings.append(f"Unresolved TODO in {fp}")

# 4. All relative links in SKILL.md resolve
for m in re.finditer(r"\]\(([^)#]+)\)", content):
    target = m.group(1)
    if target.startswith("http"): continue
    if not os.path.exists(os.path.join(os.path.dirname(skill), target)):
        errors.append(f"Broken link in SKILL.md: {target}")

# 5. JSON asset is valid JSON
json.load(open(os.path.join(base, "assets", "block-kit-message.json"), encoding="utf-8"))

# 6. Validate the .mjs files have balanced braces/parens/brackets and no stray template issues
pairs = {"{": "}", "(": ")", "[": "]"}
for root, _, files in os.walk(base):
    for f in files:
        if f.endswith(".mjs"):
            src = open(os.path.join(root, f), encoding="utf-8").read()
            stack = []
            # strip strings & comments crudely for balance check
            clean = re.sub(r"//[^\n]*|/\*.*?\*/", "", src, flags=re.S)
            clean = re.sub(r"'(?:\\.|[^'\\])*'|\"(?:\\.|[^\"\\])*\"|`(?:\\.|[^`\\])*`", "", clean, flags=re.S)
            for ch in clean:
                if ch in pairs: stack.append(pairs[ch])
                elif ch in "}])":
                    if not stack or stack.pop() != ch:
                        errors.append(f"Unbalanced delimiters in {os.path.join(root, f)}"); break
            else:
                if stack: errors.append(f"Unbalanced delimiters in {os.path.join(root, f)}")

print("Errors:", errors if errors else "none")
print("Warnings:", warnings if warnings else "none")
sys.exit(1 if errors else 0)
