import os, re, sys

def mask(src):
    out = []
    i, n = 0, len(src)
    state = "normal"
    pairs = {"{":"}","(":")","[":"]"}
    stack = []
    ok = True
    while i < n:
        c = src[i]; nxt = src[i+1] if i+1 < n else ""
        if state == "normal":
            if c == "/" and nxt == "/":
                state = "line"; i += 2; continue
            if c == "/" and nxt == "*":
                state = "block"; i += 2; continue
            if c in "\"'`":
                state = c; i += 1; continue
            if c in pairs: stack.append(pairs[c])
            elif c in "}])":
                if not stack or stack.pop() != c:
                    ok = False; break
            i += 1
        elif state == "line":
            if c == "\n": state = "normal"
            i += 1
        elif state == "block":
            if c == "*" and nxt == "/": state = "normal"; i += 2
            else: i += 1
        elif state in "\"'`":
            if c == "\\": i += 2; continue
            if c == state: state = "normal"
            i += 1
    return ok and not stack

bad = []
for root, _, files in os.walk("slack-api"):
    for f in files:
        if f.endswith(".mjs"):
            src = open(os.path.join(root, f), encoding="utf-8").read()
            if not mask(src):
                bad.append(os.path.join(root, f))
print("Delimiter check:", "FAIL -> " + ", ".join(bad) if bad else "all .mjs files balanced")
sys.exit(1 if bad else 0)
